import json
from z3 import *

# Create Z3 solver
s = Solver()

# Time bounds: 09:00 (540) to 17:55 (1075)
DAY_START = 540
DAY_END = 1075

# Places definition
# skyline_luge: cost 30, duration 90 (override), open 600-1260 (10:00-21:00)
# singapore_zoo: cost 49, duration 270 (override), open 510-1080 (08:30-18:00)
# adventure_cove: cost 40, duration 180, open 600-1020 (10:00-17:00)

places = ["skyline_luge", "adventure_cove", "singapore_zoo"]
costs = {"skyline_luge": 30, "adventure_cove": 40, "singapore_zoo": 49}
durations = {"skyline_luge": 90, "adventure_cove": 180, "singapore_zoo": 270}
open_times = {"skyline_luge": 600, "adventure_cove": 600, "singapore_zoo": 510}
close_times = {"skyline_luge": 1260, "adventure_cove": 1020, "singapore_zoo": 1080}

travel_times = {
    ("skyline_luge", "skyline_luge"): 0,
    ("skyline_luge", "adventure_cove"): 12,
    ("skyline_luge", "singapore_zoo"): 52,
    ("adventure_cove", "skyline_luge"): 12,
    ("adventure_cove", "adventure_cove"): 0,
    ("adventure_cove", "singapore_zoo"): 50,
    ("singapore_zoo", "skyline_luge"): 52,
    ("singapore_zoo", "adventure_cove"): 50,
    ("singapore_zoo", "singapore_zoo"): 0,
}

# Variables for each place
is_visited = {p: Bool(f"is_visited_{p}") for p in places}
start = {p: Int(f"start_{p}") for p in places}
end = {p: Int(f"end_{p}") for p in places}

# Must-visit places
s.add(is_visited["skyline_luge"])
s.add(is_visited["singapore_zoo"])

# Budget constraint (at most S$77)
total_cost = Sum([If(is_visited[p], costs[p], 0) for p in places])
s.add(total_cost <= 77)

for p in places:
    # Duration constraint
    s.add(end[p] == start[p] + durations[p])

    # If visited, must be within opening hours and day limits
    s.add(
        Implies(
            is_visited[p],
            And(
                start[p] >= open_times[p],
                end[p] <= close_times[p],
                start[p] >= DAY_START,
                end[p] <= DAY_END
            )
        )
    )

# No overlap and travel time between any pair of visited places
for p1 in places:
    for p2 in places:
        if p1 != p2:
            s.add(
                Implies(
                    And(is_visited[p1], is_visited[p2]),
                    Or(
                        end[p1] + travel_times[(p1, p2)] <= start[p2],
                        end[p2] + travel_times[(p2, p1)] <= start[p1]
                    )
                )
            )

if s.check() == sat:
    m = s.model()
    result = []
    for p in places:
        if is_true(m[is_visited[p]]):
            result.append({
                "location_id": p,
                "start": m[start[p]].as_long(),
                "end": m[end[p]].as_long()
            })
    # Sort by start time just to be clean
    result.sort(key=lambda x: x["start"])
    print(json.dumps(result))
else:
    print("UNSAT")
